/* Review imports from other apps (Reviews › Import, round V), on part 215's `review_imports` and `reviews.import_id` rather than beside them. On `review_imports`: `platform` (the app the file came from: Judge.me, Yotpo, Loox, Stamped.io, Okendo, Shopify Product Reviews, Reviews.io, Trustpilot, Google, Etsy, Amazon, WooCommerce, Fera, Ali Reviews, Rivyo or other), `created_by`, `total_rows`, `duplicates` (rows already on the store), `errors` (rows that could not be read), `finished_at` and `undone_count`; the table stays server only, as part 215 made it. On `reviews`: `import_key` (the app's own id for the review, as "judgeme:123", one per store, so the same file imported twice adds nothing), `content_hash` (the review's product, stars, words, name and day, so the same review exported by two apps is found too), `import_platform`, `import_verified` (the app said it was a verified purchase: shown to the store in Reviews, never as Verified purchase on the website and never in a Storelib rating) and `videos` (web addresses of a review's videos, at most two). The new columns are not readable by the public (part 134 grants reviews column by column). Run after part 215. Changes no row. Until it runs, Import works with part 215's history and Undo, finds duplicates from the reviews already imported, and keeps no app ids, videos or app verified flags. */
DO $do$ BEGIN IF to_regclass('public.review_imports') IS NULL THEN RAISE NOTICE 'review imports from apps: run part 215 first.'; RETURN; END IF; ALTER TABLE public.review_imports ADD COLUMN IF NOT EXISTS platform text NOT NULL DEFAULT 'other'; ALTER TABLE public.review_imports ADD COLUMN IF NOT EXISTS created_by uuid; ALTER TABLE public.review_imports ADD COLUMN IF NOT EXISTS total_rows integer NOT NULL DEFAULT 0; ALTER TABLE public.review_imports ADD COLUMN IF NOT EXISTS duplicates integer NOT NULL DEFAULT 0; ALTER TABLE public.review_imports ADD COLUMN IF NOT EXISTS errors integer NOT NULL DEFAULT 0; ALTER TABLE public.review_imports ADD COLUMN IF NOT EXISTS finished_at timestamptz; ALTER TABLE public.review_imports ADD COLUMN IF NOT EXISTS undone_count integer; ALTER TABLE public.review_imports DROP CONSTRAINT IF EXISTS review_imports_apps_check; ALTER TABLE public.review_imports ADD CONSTRAINT review_imports_apps_check CHECK (char_length(platform) BETWEEN 1 AND 40 AND total_rows >= 0 AND duplicates >= 0 AND errors >= 0 AND (undone_count IS NULL OR undone_count >= 0)) NOT VALID; ALTER TABLE public.review_imports ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.review_imports FROM PUBLIC, anon, authenticated; END $do$;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS import_key text;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS content_hash text;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS import_platform text;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS import_verified boolean NOT NULL DEFAULT false;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS videos jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.reviews DROP CONSTRAINT IF EXISTS reviews_import_values_check;
ALTER TABLE public.reviews ADD CONSTRAINT reviews_import_values_check CHECK (char_length(coalesce(import_key, '')) <= 200 AND char_length(coalesce(content_hash, '')) <= 64 AND char_length(coalesce(import_platform, '')) <= 40 AND jsonb_typeof(videos) = 'array' AND jsonb_array_length(videos) <= 2 AND pg_column_size(videos) < 4096) NOT VALID;
CREATE UNIQUE INDEX IF NOT EXISTS reviews_import_key_once ON public.reviews (creator_id, import_key) WHERE import_key IS NOT NULL;
CREATE INDEX IF NOT EXISTS reviews_content_hash ON public.reviews (creator_id, content_hash) WHERE content_hash IS NOT NULL;
REVOKE SELECT (import_key, content_hash, import_platform, import_verified, videos) ON public.reviews FROM anon, authenticated;
notify pgrst, 'reload schema';
